    } else {
        (self.anchor.min(term_low), self.high.max(term_high))
    };
    let span = new_high - new_low + 1;
    if span > SPAN_LIMIT_BITS {
        return Err(SumRefusal::Span);
    }
    if self.empty {
        self.anchor = new_low;
