            // reached, a bit that does not fit is refused rather than
            // dropped (RV19-N4); the sum is then unusable, and every
            // caller ends its attempt on `Span`.
            if part != 0 || carry != 0 || trimmed[k.min(limbs)..limbs].iter().any(|&w| w != 0) {
