        target[index] = s;
        carry = u64::from(c);
        index += 1;
        self.work.term_limbs += 1;
    }
    self.used = self.used.max(index.min(SUM_LIMBS));
    self.work.term_limbs += limbs as u64 + 1;
    Ok(())
