pub(crate) fn from_integer(
    &mut self,
    negative: bool,
    magnitude: &[u64],
    exponent: i64,
) -> Result<Wide<L>, WideError> {
    self.work.charge(OpKind::Round);
    from_integer_rounded::<L>(negative, magnitude, exponent, self.precision)
}

